result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/cron.py", "content": """"A minimal cron expression library.

Supports standard 5-field crontab syntax:

    minute hour day-of-month month day-of-week

Features: ``*``, lists (``1,15``), ranges (``9-17``), steps (``*/15``,
``3-59/20``), month names (JAN-DEC) and weekday names (SUN-SAT),
case-insensitive.

Follows the vixie-cron rule for matching: when both day-of-month and
day-of-week are restricted (i.e. not ``*``), a date matches if *either*
field matches.
"""

from __future__ import annotations

import calendar
from datetime import datetime, timedelta

__all__ = ["CronError", "parse", "next_fire"]

_MINUTE_MIN, _MINUTE_MAX = 0, 59
_HOUR_MIN, _HOUR_MAX = 0, 23
_DOM_MIN, _DOM_MAX = 1, 31
_MONTH_MIN, _MONTH_MAX = 1, 12
_DOW_MIN, _DOW_MAX = 0, 6  # 0 = Sunday (vixie-cron convention)

_MONTH_NAMES = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}
_DOW_NAMES = {
    "sun": 0, "mon": 1, "tue": 2, "wed": 3, "thu": 4, "fri": 5, "sat": 6,
}


class CronError(ValueError):
    """Raised when a cron expression cannot be parsed."""


def _lookup_name(token: str, names: dict[str, int], field: str) -> int:
    try:
        return names[token]
    except KeyError:
        raise CronError(
            f"invalid value {token!r} in field {field!r}"
        ) from None


def _parse_value(token: str, lo: int, hi: int, field: str,
                 names: dict[str, int] | None) -> int:
    if names:
        as_int = token.lower()
        if not as_int.lstrip("-").isdigit():
            return _lookup_name(as_int, names, field)
    try:
        value = int(token)
    except ValueError:
        raise CronError(
            f"invalid value {token!r} in field {field!r}"
        ) from None
    if not lo <= value <= hi:
        raise CronError(
            f"value {value} out of range {lo}-{hi} "
            f"in field {field!r}"
        )
    return value


def _parse_field(spec: str, lo: int, hi: int, field: str,
                 names: dict[str, int] | None = None) -> frozenset[int]:
    """Parse one cron field into a set of allowed values."""
    values: set[int] = set()
    for part in spec.split(","):
        part = part.strip()
        if not part:
            raise CronError(f"empty list item in field {field!r}")

        step = 1
        if "/" in part:
            part, step_str = part.split("/", 1)
            if not step_str.isdigit() or int(step_str) == 0:
                raise CronError(
                    f"invalid step {step_str!r} in field {field!r}"
                )
            step = int(step_str)

        def add_range(start_tok: str, end_tok: str | None) -> None:
            start = _parse_value(start_tok, lo, hi, field, names)
            if end_tok is None:
                end = start
            else:
                end = _parse_value(end_tok, lo, hi, field, names)
            if end < start:
                raise CronError(
                    f"range {start}-{end} is reversed in field {field!r}"
                )
            values.update(range(start, end + 1, step))

        if part == "*":
            if "/" in spec or step > 1:
                values.update(range(lo, hi + 1, step))
            else:
                values.update(range(lo, hi + 1))
        elif "-" in part.lstrip("-"):
            # range (guard against negative numbers, which cron doesn't have;
            # a leading '-' here would only occur on malformed input)
            start_tok, end_tok = part.split("-", 1)
            add_range(start_tok, end_tok)
        else:
            if step > 1:
                # e.g. "5/15" == "5-hi/15" (vixie-cron extension)
                start = _parse_value(part, lo, hi, field, names)
                values.update(range(start, hi + 1, step))
            else:
                values.add(_parse_value(part, lo, hi, field, names))

    if not values:
        raise CronError(f"no valid values in field {field!r}")
    return frozenset(values)


def parse(expr: str) -> tuple[frozenset[int], frozenset[int],
                               frozenset[int] | None,
                               frozenset[int], frozenset[int] | None]:
    """Parse a 5-field cron expression.

    Returns ``(minutes, hours, dom, months, dow)`` where ``dom`` and
    ``dow`` are ``None`` when the field is unrestricted (``*``),
    otherwise the set of allowed values.
    """
    if not isinstance(expr, str):
        raise CronError("cron expression must be a string")
    fields = expr.split()
    if len(fields) != 5:
        raise CronError(
            f"expected 5 fields (minute hour dom month dow), "
            f"got {len(fields)}: {expr!r}"
        )

    minutes = _parse_field(fields[0], _MINUTE_MIN, _MINUTE_MAX, "minute")
    hours = _parse_field(fields[1], _HOUR_MIN, _HOUR_MAX, "hour")
    dom_spec, month_spec, dow_spec = fields[2], fields[3], fields[4]

    dom = (None if dom_spec == "*"
           else _parse_field(dom_spec, _DOM_MIN, _DOM_MAX, "day-of-month"))
    months = _parse_field(month_spec, _MONTH_MIN, _MONTH_MAX, "month",
                          _MONTH_NAMES)
    dow = (None if dow_spec == "*"
           else _parse_field(dow_spec, _DOW_MIN, _DOW_MAX, "day-of-week",
                             _DOW_NAMES))

    return minutes, hours, dom, months, dow


def _matches_date(dt: datetime, dom: frozenset[int] | None,
                  months: frozenset[int], dow: frozenset[int] | None) -> bool:
    """vixie-cron date matching: if both dom and dow are restricted,
    match when either matches; otherwise both must match."""
    month_ok = dt.month in months
    if not month_ok:
        return False
    if dom is None and dow is None:
        day_ok = True
    elif dom is not None and dow is not None:
        # Python: Monday=0 .. Sunday=6; cron: Sunday=0 .. Saturday=6
        cron_dow = (dt.weekday() + 1) % 7
        day_ok = dt.day in dom or cron_dow in dow
    elif dom is not None:
        day_ok = dt.day in dom
    else:
        assert dow is not None
        cron_dow = (dt.weekday() + 1) % 7
        day_ok = cron_dow in dow
    return day_ok


def next_fire(expr: str, after: datetime) -> datetime:
    """Return the next minute strictly after ``after`` that matches ``expr``.

    Microseconds of ``after`` are ignored (cron fires at whole minutes).
    """
    minutes, hours, dom, months, dow = parse(expr)

    # Start at the next whole minute strictly after `after`.
    candidate = (after + timedelta(minutes=1)).replace(second=0, microsecond=0)

    # Search forward; bail out after ~4 years to avoid infinite loops on
    # impossible dates like Feb 30.
    limit = candidate.replace(year=candidate.year + 4)
    while candidate < limit:
        if not _matches_date(candidate, dom, months, dow):
            # Jump to midnight of the next day.
            candidate = (candidate + timedelta(days=1)).replace(hour=0,
                                                                minute=0)
            continue
        if candidate.hour not in hours:
            # Next hour whose hour value is allowed.
            h = candidate.hour
            while True:
                h += 1
                if h > _HOUR_MAX:
                    break
                if h in hours:
                    candidate = candidate.replace(hour=h, minute=0)
                    break
            else:  # pragma: no cover - loop always breaks
                pass
            if candidate.hour not in hours:
                candidate = (candidate + timedelta(days=1)).replace(hour=0,
                                                                    minute=0)
                continue
            continue  # re-check date (replace may cross into new hour only)
        if candidate.minute not in minutes:
            m = min((x for x in minutes if x > candidate.minute), default=None)
            if m is None:
                candidate = (candidate + timedelta(hours=1)).replace(minute=0)
            else:
                candidate = candidate.replace(minute=m)
            continue
        return candidate

    raise CronError(f"expression {expr!r} never fires within 4 years")
